const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries
  const brycCanyon = ee.Geometry.Point([-112.1871, 37.5790]); // Bryce Canyon center
  const lasVegas = ee.Geometry.Point([-115.1372, 36.1699]); // Las Vegas center

  // Buffer to create regions (10km radius)
  const brycBuffer = brycCanyon.buffer(10000);
  const vegasBuffer = lasVegas.buffer(10000);

  // Load VIIRS Nighttime Lights data for 2024
  const startDate = '2024-01-01';
  const endDate = '2024-12-31';

  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V21')
    .filterDate(startDate, endDate)
    .select('avg_rad'); // Average radiance band

  // Check if collection is empty
  const collectionSize = viirs.size().getInfo();
  if (collectionSize === 0) {
    console.log('No VIIRS data available for 2024.');
    console.log('C1');
    return;
  }

  console.log(`VIIRS 2024 Images: ${collectionSize}`);

  // Create annual composites (mean of all monthly data)
  const viirs2024 = viirs.mean();

  // Calculate mean nighttime radiance for both locations
  const brycStats = viirs2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: brycBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const vegasStats = viirs2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: vegasBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get pixel counts to validate data
  const brycCount = viirs2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: brycBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const vegasCount = viirs2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vegasBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const brycRadiance = brycStats.get('avg_rad').getInfo();
  const vegasRadiance = vegasStats.get('avg_rad').getInfo();
  const brycPixels = brycCount.get('avg_rad').getInfo();
  const vegasPixels = vegasCount.get('avg_rad').getInfo();

  // Validate data
  if (brycPixels === 0 || vegasPixels === 0) {
    console.log(`Valid pixels - Bryce: ${brycPixels}, Vegas: ${vegasPixels}`);
    console.log('C2');
    return;
  }

  if (brycRadiance === null || vegasRadiance === null || 
      isNaN(brycRadiance) || isNaN(vegasRadiance)) {
    console.log('Calculation resulted in null or NaN values.');
    console.log('C3');
    return;
  }

  // Output statistics
  console.log(`Bryce Canyon 2024 Radiance: ${brycRadiance.toFixed(4)} (Pixels: ${brycPixels})`);
  console.log(`Las Vegas 2024 Radiance: ${vegasRadiance.toFixed(4)} (Pixels: ${vegasPixels})`);

  // Determine if Bryce Canyon is lower than Las Vegas
  const brycLower = brycRadiance < vegasRadiance;

  if (brycLower) {
    console.log('Bryce Canyon nighttime intensity IS lower than Las Vegas.');
    console.log('A');
  } else {
    console.log('Bryce Canyon nighttime intensity is NOT lower than Las Vegas.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
